"""Reviewed-source gate around an operator-supplied Native crest adapter.

The delegate owns CARLA actors, sensors and world settings. This wrapper checks
the original highway/lane documents and live map before delegate.begin mutates
the scene; native_capture.capture owns delegate.close in its finally clause.
"""
from __future__ import annotations

import hashlib
import json
from pathlib import Path

from native_capture import ONE_WAY_AUTHORITY


def _read_source(root: Path, item: dict, kind: str, case_id: str,
                 map_sha256: str) -> tuple[bytes, str]:
    if not isinstance(item, dict) or not item.get("reviewer") or not item.get("source_citation"):
        raise ValueError("Reviewed source provenance missing: " + kind)
    name = item.get("path")
    if not isinstance(name, str) or not name or Path(name).is_absolute() or ".." in Path(name).parts or "\\" in name:
        raise ValueError("Unsafe original source path: " + kind)
    parts = [root.joinpath(*Path(name).parts[:i]) for i in range(1, len(Path(name).parts) + 1)]
    if any(part.is_symlink() for part in parts):
        raise ValueError("Symlinked original source path: " + kind)
    data = (root / name).read_bytes()
    digest = hashlib.sha256(data).hexdigest()
    if digest != item.get("sha256"):
        raise ValueError("Original source hash mismatch: " + kind)
    document = json.loads(data)
    if (document.get("source_kind") != kind or
            document.get("source_citation") != item["source_citation"] or
            document.get("case_id") != case_id or
            document.get("map_opendrive_sha256") != map_sha256):
        raise ValueError("Original source claim mismatch: " + kind)
    required_facts = {"highway": "public_highway",
                      "center_reference": "center_reference_present",
                      "opposing_lane": "opposing_direction_present",
                      "one_way_authority": "one_way_designation"}
    if document.get(required_facts[kind]) is not True:
        raise ValueError("Original source fact missing: " + kind)
    return data, digest


class ReviewedAdapter:
    def __init__(self, delegate, *, packet_path: Path, source_root: Path, output: Path, world):
        self.delegate = delegate
        self.packet_path = Path(packet_path)
        self.source_root = Path(source_root)
        self.output = Path(output)
        self.world = world

    def begin(self, case_id):
        packet = json.loads(self.packet_path.read_bytes())
        if (packet.get("case_id") != case_id or packet.get("law_id") != "NRS-484B-213-2a"
                or not packet.get("reviewer") or not packet.get("source_citation")):
            raise ValueError("Reviewed crest packet identity missing")
        map_digest = hashlib.sha256(self.world.get_map().to_opendrive().encode()).hexdigest()
        if packet.get("map_opendrive_sha256") != map_digest:
            raise ValueError("Reviewed crest map hash mismatch")
        one_way = case_id.endswith("__left_one_way_obstructed")
        required = ("highway", "center_reference", "one_way_authority" if one_way else "opposing_lane")
        sources = packet.get("sources")
        if not isinstance(sources, dict) or set(sources) != set(required):
            raise ValueError("Exact crest source inventory missing")
        retained = {kind: _read_source(self.source_root, sources[kind], kind,
                                      case_id, map_digest) for kind in required}
        context = self.delegate.begin(case_id)
        if (not isinstance(context, dict) or context.get("case_id") != case_id
                or context.get("law_id") != packet["law_id"]
                or context.get("highway_source_ref") != retained["highway"][1]
                or context.get("center_reference_source_ref") != retained["center_reference"][1]):
            raise ValueError("Native context differs from reviewed crest sources")
        if one_way:
            authority = context.get("one_way_authority")
            if (context.get("lane_allocation") != "one_way" or not isinstance(authority, dict)
                    or authority.get("sha256") != retained["one_way_authority"][1]
                    or authority.get("source_ref") != sources["one_way_authority"]["source_citation"]):
                raise ValueError("Native one-way context differs from authority")
            target = self.output / ONE_WAY_AUTHORITY
            if target.exists() or target.is_symlink():
                raise ValueError("Original one-way authority output already exists")
            target.write_bytes(retained["one_way_authority"][0])
        elif (context.get("lane_allocation") != "two_way"
              or context.get("opposing_lane_source_ref") != retained["opposing_lane"][1]):
            raise ValueError("Native opposing-lane context differs from review")
        for kind in required:
            target = self.output / ("reviewed-" + kind + ".json")
            if target.exists() or target.is_symlink():
                raise ValueError("Original reviewed source output already exists")
            target.write_bytes(retained[kind][0])
        return context

    def tick(self):
        return self.delegate.tick()

    def sample(self, frame):
        return self.delegate.sample(frame)

    def camera_frames(self, frame):
        return self.delegate.camera_frames(frame)

    def graph_observer(self, frame, time_s):
        return self.delegate.graph_observer(frame, time_s)

    def write_camera_video(self, camera, path):
        return self.delegate.write_camera_video(camera, path)

    def close(self):
        return self.delegate.close()

"""Source-gated crest and opposing-lane geometry for NRS 484B.213(2)(a).

The real capture must supply original map waypoint samples. Targets here are
engineering probes, not definitions of the statutory hazard judgment.
"""
from __future__ import annotations

import math


def _number(value):
    return type(value) in (int, float) and math.isfinite(value)


def validate_lanes(ego, opposite):
    """Require two original, opposite-direction lanes on the same road."""
    if not isinstance(ego, list) or not isinstance(opposite, list) or len(ego) < 3 or len(opposite) < 3:
        raise ValueError('original ego and opposing waypoint samples required')
    for lane in (ego, opposite):
        for point in lane:
            if not isinstance(point, dict) or not all(_number(point.get(k)) for k in ('s_m', 'x_m', 'y_m', 'road_z_m')):
                raise ValueError('finite original waypoint coordinates required')
            if not point.get('source_ref') or point.get('road_id') is None or point.get('lane_id') is None:
                raise ValueError('original waypoint provenance and road/lane IDs required')
        if any(b['s_m'] <= a['s_m'] for a, b in zip(lane, lane[1:])):
            raise ValueError('waypoint stations must increase')
        if len({p['road_id'] for p in lane}) != 1 or len({p['lane_id'] for p in lane}) != 1:
            raise ValueError('route changes road or lane')
    if ego[0]['road_id'] != opposite[0]['road_id'] or ego[0]['lane_id'] == opposite[0]['lane_id']:
        raise ValueError('opposing lane must be distinct on the same road')
    if ego[0].get('travel_direction') != 'increasing_s' or opposite[0].get('travel_direction') != 'decreasing_s':
        raise ValueError('original lane travel directions do not oppose')
    if any(p.get('travel_direction') != 'increasing_s' for p in ego) or any(p.get('travel_direction') != 'decreasing_s' for p in opposite):
        raise ValueError('inconsistent lane direction history')
    if any(abs(a['s_m'] - b['s_m']) > 0.1 for a, b in zip(ego, opposite)) or len(ego) != len(opposite):
        raise ValueError('opposing lane station coverage differs')
    if any(abs(a['road_z_m'] - b['road_z_m']) > 0.5 for a, b in zip(ego, opposite)):
        raise ValueError('lanes do not share a credible road grade')
    return True


def crest_occlusion(ego, opposite, *, observer_s_m, target_s_m, eye_height_m=1.4,
                     body_height_m=1.4):
    """Return sampled grade intersection, never a legal visibility conclusion."""
    validate_lanes(ego, opposite)
    if not all(_number(v) for v in (observer_s_m, target_s_m, eye_height_m, body_height_m)):
        raise ValueError('finite observer and target measurements required')
    if observer_s_m >= target_s_m or eye_height_m <= 0 or body_height_m <= 0:
        raise ValueError('observer must approach an opposing target in station order')
    points = {p['s_m']: p for p in ego}
    if observer_s_m not in points or target_s_m not in points:
        raise ValueError('observer and target require original waypoint samples')
    eye_z = points[observer_s_m]['road_z_m'] + eye_height_m
    target_z = points[target_s_m]['road_z_m'] + body_height_m
    blockers = []
    for p in ego:
        s = p['s_m']
        if observer_s_m < s < target_s_m:
            ray_z = eye_z + (target_z - eye_z) * (s - observer_s_m) / (target_s_m - observer_s_m)
            if p['road_z_m'] > ray_z:
                blockers.append({'s_m': s, 'excess_height_m': p['road_z_m'] - ray_z,
                                 'source_ref': p['source_ref']})
    return {'sampled_grade_blocks_proxy_ray': bool(blockers), 'blockers': blockers,
            'observer_s_m': observer_s_m, 'target_s_m': target_s_m,
            'proxy_limitations': 'Sampled road grade and virtual observer only; Native raycasts, actual bodies, pixels and hazard judgment remain unverified.'}

"""Independent source-bound four-camera full-decode check for saved Native attempts.

This is a CPU delivery guard, not proof that an actor or crest is visible.
"""
from __future__ import annotations

import hashlib
import json
import math
import re
import subprocess
from fractions import Fraction
from pathlib import Path

CAMERAS = ('overview', 'approach', 'reference_corner', 'driver_reference')


def _run(command):
    result = subprocess.run(command, text=True, capture_output=True, check=False)
    if result.returncode:
        raise ValueError(f'media decode failed: {result.stderr[-600:]}')
    return result.stdout


def audit(attempt_dir, source_hashes, *, expected_frames=900, expected_fps=20,
          expected_dimensions=None):
    """Reopen exact originals, count and decode every frame of every camera."""
    attempt = Path(attempt_dir).resolve()
    if type(expected_frames) is not int or expected_frames <= 0:
        raise ValueError('invalid required frame count')
    if type(expected_fps) is not int or expected_fps <= 0:
        raise ValueError('invalid required frame rate')
    if expected_dimensions is not None and (not isinstance(expected_dimensions, dict)
            or set(expected_dimensions) != set(CAMERAS)):
        raise ValueError('incomplete camera dimension plan')
    receipts = {}
    for camera in CAMERAS:
        name = f'{camera}.mkv'
        expected_hash = source_hashes.get(name)
        if not isinstance(expected_hash, str) or not re.fullmatch(r'[0-9a-f]{64}', expected_hash):
            raise ValueError(f'camera source hash missing: {name}')
        source = attempt / name
        if source.is_symlink() or not source.is_file() or source.resolve().parent != attempt:
            raise ValueError(f'camera original missing or escapes attempt: {name}')
        actual_hash = hashlib.sha256(source.read_bytes()).hexdigest()
        if actual_hash != expected_hash:
            raise ValueError(f'camera original changed: {name}')
        probe = json.loads(_run(['ffprobe', '-v', 'error', '-count_frames',
                                 '-select_streams', 'v:0', '-show_entries',
                                 'stream=codec_name,width,height,r_frame_rate,nb_read_frames',
                                 '-of', 'json', str(source)]))
        streams = probe.get('streams') or []
        if len(streams) != 1:
            raise ValueError(f'camera video stream missing: {name}')
        stream = streams[0]
        if Fraction(stream.get('r_frame_rate', '0/1')) != expected_fps:
            raise ValueError(f'camera frame rate mismatch: {name}')
        if int(stream.get('nb_read_frames', -1)) != expected_frames:
            raise ValueError(f'camera frame count mismatch: {name}')
        width, height = stream.get('width'), stream.get('height')
        if type(width) is not int or type(height) is not int or width <= 0 or height <= 0:
            raise ValueError(f'camera dimensions missing: {name}')
        if expected_dimensions is not None and (width, height) != tuple(expected_dimensions[camera]):
            raise ValueError(f'camera dimensions mismatch: {name}')
        frame_probe = json.loads(_run(['ffprobe', '-v', 'error',
                                       '-select_streams', 'v:0',
                                       '-show_entries', 'frame=best_effort_timestamp_time',
                                       '-of', 'json', str(source)]))
        frames = frame_probe.get('frames')
        if not isinstance(frames, list) or len(frames) != expected_frames:
            raise ValueError(f'camera presentation frame count mismatch: {name}')
        for index, frame in enumerate(frames):
            try:
                presentation = float(frame['best_effort_timestamp_time'])
            except (KeyError, TypeError, ValueError) as error:
                raise ValueError(f'camera presentation timestamp missing: {name}') from error
            if not math.isfinite(presentation) or abs(presentation - index / expected_fps) > 0.002:
                raise ValueError(f'camera presentation timing mismatch: {name}')
        _run(['ffmpeg', '-v', 'error', '-xerror', '-i', str(source), '-map', '0:v:0',
              '-f', 'null', '-'])
        receipts[camera] = {'source': name, 'sha256': actual_hash,
                            'codec': stream.get('codec_name'), 'frames_decoded': expected_frames,
                            'fps': expected_fps, 'width': width, 'height': height,
                            'presentation_timing_checked': True}
    return {'format': 'crest-four-camera-decode', 'origin_verified': False,
            'cameras': receipts, 'physical_visibility_reviewed': False,
            'limitations': 'Full source decode establishes readable synchronized media shape, not actual vehicle, crest, or sight-line visibility.'}

"""Independent source-presence and fixed-condition checks for crest comparisons.

This checker verifies recorded packet isolation only. It does not adjudicate the
statutory hazard-distance phrase or certify physical capture quality.
"""
import json
import re
from pathlib import Path

REQUIRED = ('case_id', 'source_ref', 'law_id', 'actor', 'map_source', 'camera_profile',
            'duration_frames', 'crest_grade_sha256', 'ego_route_sha256',
            'other_route_sha256', 'other_timing_sha256', 'lane_allocation',
            'ego_left_side_observed', 'sampled_grade_blocks_proxy_ray')
COMPARISONS = {
    'left_side_motion': {
        'suffixes': ('right_crest_obstructed', 'left_crest_obstructed'),
        'fixed': ('law_id', 'actor', 'map_source', 'camera_profile', 'duration_frames',
                  'crest_grade_sha256', 'other_route_sha256', 'other_timing_sha256',
                  'lane_allocation', 'sampled_grade_blocks_proxy_ray'),
        'difference': ('ego_left_side_observed',),
    },
    'crest_view_obstruction': {
        'suffixes': ('left_crest_obstructed', 'left_crest_clear'),
        'fixed': ('law_id', 'actor', 'camera_profile', 'duration_frames',
                  'ego_route_sha256', 'other_route_sha256', 'other_timing_sha256',
                  'lane_allocation', 'ego_left_side_observed'),
        'difference': ('crest_grade_sha256', 'sampled_grade_blocks_proxy_ray'),
    },
    'one_way_exception': {
        'suffixes': ('left_crest_obstructed', 'left_one_way_obstructed'),
        'fixed': ('law_id', 'actor', 'camera_profile', 'duration_frames',
                  'ego_left_side_observed', 'sampled_grade_blocks_proxy_ray'),
        'difference': ('lane_allocation',),
    },
}


def audit(comparison_id, first, second, assignment_id):
    spec = COMPARISONS[comparison_id]
    for packet, suffix in zip((first, second), spec['suffixes']):
        if not isinstance(packet, dict) or any(k not in packet or packet[k] is None for k in REQUIRED):
            raise ValueError('missing source-bound comparison packet field')
        if packet['case_id'] != f'{assignment_id}__{suffix}' or not packet['source_ref']:
            raise ValueError('wrong exact case or missing original source')
        if packet['law_id'] != 'NRS-484B-213-2a' or packet['actor'] != 'motor_vehicle_driver':
            raise ValueError('law or actor drift')
        if packet['lane_allocation'] not in ('two_way', 'one_way') or type(packet['ego_left_side_observed']) is not bool or type(packet['sampled_grade_blocks_proxy_ray']) is not bool:
            raise ValueError('invalid observed lane or body state')
        if packet['lane_allocation'] == 'one_way':
            authority = packet.get('one_way_authority_source_ref')
            digest = packet.get('one_way_authority_sha256')
            if not isinstance(authority, str) or not authority or not isinstance(digest, str) or not re.fullmatch(r'[0-9a-f]{64}', digest):
                raise ValueError('one-way exception lacks original authority source and SHA256')
    for field in spec['fixed']:
        if first[field] != second[field]:
            raise ValueError(f'confounded fixed condition: {field}')
    for field in spec['difference']:
        if first[field] == second[field]:
            raise ValueError(f'missing deliberate difference: {field}')
    if comparison_id != 'one_way_exception' and any(p['lane_allocation'] != 'two_way' for p in (first, second)):
        raise ValueError('two-way comparison lacks opposing lane')
    if comparison_id == 'left_side_motion' and (first['ego_left_side_observed'], second['ego_left_side_observed']) != (False, True):
        raise ValueError('left-side motion order wrong')
    if comparison_id == 'crest_view_obstruction' and (first['sampled_grade_blocks_proxy_ray'], second['sampled_grade_blocks_proxy_ray']) != (True, False):
        raise ValueError('crest proxy-ray comparison order wrong')
    if comparison_id == 'one_way_exception' and (first['lane_allocation'], second['lane_allocation']) != ('two_way', 'one_way'):
        raise ValueError('one-way exception order wrong')
    return {'comparison_id': comparison_id, 'passed': True,
            'scope': 'source-packet field isolation only; physical and legal review pending'}


def main():
    import argparse
    parser = argparse.ArgumentParser()
    parser.add_argument('--comparison', required=True, choices=COMPARISONS)
    parser.add_argument('--first', required=True)
    parser.add_argument('--second', required=True)
    parser.add_argument('--assignment', required=True)
    args = parser.parse_args()
    result = audit(args.comparison, json.loads(Path(args.first).read_text()),
                   json.loads(Path(args.second).read_text()), args.assignment)
    print(json.dumps(result, sort_keys=True))


if __name__ == '__main__':
    main()
